(function(){const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,(c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])));let EQUIPO=null;async function equipo(sb){if(EQUIPO)return EQUIPO;const{data:data}=await sb.from("usuarios").select("email, nombre, activo").eq("activo",true).order("email");EQUIPO=data||[];return EQUIPO}async function ultimoCambio(sb,tabla,filaId){const{data:data}=await sb.from("correcciones_datos").select("valor_anterior, valor_nuevo, motivo, corregido_en, corregido_por").eq("tabla",tabla).eq("fila_id",filaId).eq("campo","creado_por").order("corregido_en",{ascending:false}).limit(1).maybeSingle();return data||null}async function reasignar(sb,{tabla:tabla,filaId:filaId,actual:actual,nuevo:nuevo,motivo:motivo}){if(!nuevo)return{error:"Falta el nuevo autor."};if(nuevo===actual)return{error:"Ese ya es el autor."};if(!motivo||motivo.trim().length<3)return{error:"Escribe el motivo: es lo que explica el cambio dentro de un año."};const{error:error}=await sb.rpc("reasigna_autor",{p_tabla:tabla,p_fila:filaId,p_nuevo:nuevo,p_motivo:motivo.trim()});if(error)return{error:"No se ha cambiado nada: "+error.message};return{ok:true}}async function montar(slot,{sb:sb,ficha:ficha,tabla:tabla,filaId:filaId,actual:actual,editable:editable,motivoNoEditable:motivoNoEditable,onCambio:onCambio}){if(!slot||!sb)return;if(!ficha||ficha.rol!=="super_admin")return;slot.classList.add("lw-autoria");slot.innerHTML='<button type="button" class="lw-autoria-abrir">Reasignar autor</button>';const abrir=slot.querySelector("button");abrir.onclick=async ev=>{ev.stopPropagation();if(slot.querySelector(".lw-autoria-caja")){cerrar();return}abrir.disabled=true;const[lista,ultimo]=await Promise.all([equipo(sb),ultimoCambio(sb,tabla,filaId)]);abrir.disabled=false;const opciones=lista.filter((u=>u.email!==actual)).map((u=>`<option value="${esc(u.email)}">${esc(u.nombre||u.email)}</option>`)).join("");const caja=document.createElement("div");caja.className="lw-autoria-caja";caja.innerHTML=`\n        <p class="lw-autoria-actual">Autor actual: <b>${esc(actual||"sin autor")}</b></p>\n        ${ultimo?`<p class="lw-autoria-hist">Ya se reasignó el ${esc(String(ultimo.corregido_en).slice(0,10))}\n            por ${esc(ultimo.corregido_por||"—")}: ${esc(ultimo.valor_anterior||"—")} → ${esc(ultimo.valor_nuevo||"—")}</p>`:""}\n        ${editable?`\n          <label>Nuevo autor\n            <select class="lw-autoria-quien">${opciones||'<option value="">No hay nadie más en el equipo</option>'}</select>\n          </label>\n          <label>Motivo\n            <input class="lw-autoria-motivo" type="text" maxlength="180" placeholder="Ej. lo creó Ana con mi cuenta por error">\n          </label>\n          <div class="lw-autoria-pie">\n            <button type="button" class="lw-autoria-ok">Reasignar</button>\n            <button type="button" class="lw-autoria-no">Cancelar</button>\n          </div>\n          <p class="lw-autoria-aviso" hidden></p>`:`<p class="lw-autoria-hist">${esc(motivoNoEditable||"Esta fila no admite cambios.")}</p>`}`;slot.appendChild(caja);caja.onclick=e=>e.stopPropagation();const $=s=>caja.querySelector(s);if(!editable)return;$(".lw-autoria-quien").focus();$(".lw-autoria-no").onclick=cerrar;$(".lw-autoria-ok").onclick=async()=>{const aviso=$(".lw-autoria-aviso");const boton=$(".lw-autoria-ok");boton.disabled=true;boton.textContent="Reasignando…";const nuevo=$(".lw-autoria-quien").value;const r=await reasignar(sb,{tabla:tabla,filaId:filaId,actual:actual,nuevo:nuevo,motivo:$(".lw-autoria-motivo").value});boton.disabled=false;boton.textContent="Reasignar";if(r.error){aviso.hidden=false;aviso.textContent=r.error;return}cerrar();if(typeof onCambio==="function")onCambio(nuevo)}};function cerrar(){const c=slot.querySelector(".lw-autoria-caja");if(c)c.remove()}}const css=`\n  .lw-autoria{ position:relative; display:inline-block; }\n  .lw-autoria-abrir{ font:inherit; font-size:11.5px; letter-spacing:.04em; color:inherit; opacity:.75;\n    background:none; border:1px solid currentColor; border-radius:999px; padding:3px 9px; cursor:pointer; }\n  .lw-autoria-abrir:hover{ opacity:1; }\n  .lw-autoria-abrir:disabled{ opacity:.4; cursor:default; }\n  .lw-autoria-caja{ position:absolute; right:0; top:calc(100% + 6px); z-index:80; width:290px; text-align:left;\n    background:#fff; color:#22282A; border:1px solid #E2DACA; border-radius:12px; padding:13px 14px;\n    box-shadow:0 12px 30px -14px rgba(46,52,55,.4); font-size:12.5px; }\n  .lw-autoria-caja label{ display:block; margin:9px 0 0; font-size:11px; letter-spacing:.06em;\n    text-transform:uppercase; color:#4A5052; }\n  .lw-autoria-caja select, .lw-autoria-caja input{ width:100%; font:inherit; font-size:12.5px; margin-top:4px;\n    padding:6px 8px; border:1px solid #E2DACA; border-radius:8px; background:#fff; color:#22282A; }\n  .lw-autoria-actual{ margin:0; }\n  .lw-autoria-hist{ margin:6px 0 0; color:#4A5052; line-height:1.45; }\n  .lw-autoria-pie{ display:flex; gap:8px; margin-top:11px; }\n  .lw-autoria-pie button{ font:inherit; font-size:12px; border-radius:999px; padding:6px 13px; cursor:pointer;\n    border:1px solid #485B37; }\n  .lw-autoria-ok{ background:#485B37; color:#fff; }\n  .lw-autoria-no{ background:none; color:#4A5052; border-color:#E2DACA; }\n  .lw-autoria-aviso{ margin:9px 0 0; color:#8A2E22; line-height:1.45; }`;const hoja=document.createElement("style");hoja.textContent=css;document.head.appendChild(hoja);window.LW_AUTORIA={montar:montar,reasignar:reasignar,equipo:equipo,ultimoCambio:ultimoCambio,puede:ficha=>!!ficha&&ficha.rol==="super_admin"}})();